        _hole2.addQuadCurve(to: CGPoint(x: 0.7899583333*width, y: 0.4925833333*height), control: CGPoint(x: 0.7797916667*width, y: 0.4925833333*height))
        path.addReversedPath(_hole2)
        return path
    }
}